package com.miraya.kostku

import org.json.JSONObject

// Grup API untuk penghuni: penempatan, perpanjangan, pindah, keluar, dan audit.

internal suspend fun KostkuApi.createTenantPlacement(fullName:String,phone:String,propertyId:String,roomTypeId:String,roomId:String,priceId:String,moveInAt:String,moveOutAt:String,monthlyRent:Int,amountPaid:Int,paymentStatus:String,discountType:String?,discountValue:Int,method:String="other",category:String?=null)=runCatching{val moveInDate=moveInAt.substringBefore(' ');val dueDay=moveInDate.substringAfterLast('-').toIntOrNull()?:1;obj(request("tenants","POST",JSONObject().put("full_name",fullName).put("phone",phone).put("property_id",propertyId).put("room_type_id",roomTypeId).put("room_id",roomId).put("price_id",priceId).put("move_in_at",moveInAt).put("move_in_date",moveInDate).put("move_out_at",moveOutAt).put("move_out_date",moveOutAt.substringBefore(' ')).put("monthly_rent",monthlyRent).put("due_day",dueDay).put("amount_paid",amountPaid).put("payment_status",paymentStatus).put("discount_type",discountType).put("discount_value",discountValue).put("method",method).putOpt("category",category)))}
internal suspend fun KostkuApi.extendTenant(id:String,moveOutDate:String,monthlyRent:Int,amountPaid:Int,paymentStatus:String,method:String="other",category:String?=null,discountType:String?=null,discountValue:Int=0)=runCatching{obj(request("tenants/$id/extend","POST",JSONObject().put("move_out_date",moveOutDate).put("monthly_rent",monthlyRent).put("amount_paid",amountPaid).put("payment_status",paymentStatus).put("method",method).putOpt("category",category).putOpt("discount_type",discountType).put("discount_value",discountValue)))}
internal suspend fun KostkuApi.createTenant(roomId:String,name:String,phone:String,moveIn:String,rent:Int,due:Int)=runCatching{obj(request("tenants","POST",JSONObject().put("room_id",roomId).put("full_name",name).put("phone",phone).put("move_in_date",moveIn).put("monthly_rent",rent).put("due_day",due)))}
internal suspend fun KostkuApi.updateTenant(id:String,name:String,phone:String,email:String?,identityNumber:String?,notes:String?,monthlyRent:Int?=null,dueDay:Int?=null,moveInDate:String?=null,moveOutDate:String?=null):JSONObject=obj(request("tenants/$id","PATCH",JSONObject().put("full_name",name).put("phone",phone).putOpt("email",email).putOpt("identity_number",identityNumber).putOpt("notes",notes).apply{monthlyRent?.let{put("monthly_rent",it)};dueDay?.let{put("due_day",it)};moveInDate?.let{put("move_in_date",it)};moveOutDate?.let{put("move_out_date",it)}}))
internal suspend fun KostkuApi.deleteTenant(id:String)=runCatching{request("tenants/$id","DELETE")}
internal suspend fun KostkuApi.moveOut(id:String,date:String,roomStatus:String="vacant")=runCatching{request("tenants/$id/move-out","POST",JSONObject().put("move_out_date",date).put("room_status",roomStatus))}
internal suspend fun KostkuApi.moveTenant(id:String,roomId:String)=runCatching{request("tenants/$id/move","POST",JSONObject().put("room_id",roomId))}
internal suspend fun KostkuApi.tenantAudit(tenantId:String)=runCatching{val a=arr(request("tenants/$tenantId/audit")); (0 until a.length()).map { val o=a.getJSONObject(it); RemoteAuditEntry(o.optString("id"),o.optString("action"),o.optText("details"),o.optText("created_at_wib") ?: o.optString("created_at")) }}
internal suspend fun KostkuApi.moveOutHistory(month:String)=runCatching{val a=arr(request("tenants/move-out-history?month=$month")); (0 until a.length()).map { val o=a.getJSONObject(it); RemoteMoveOutHistory(o.optString("id"),o.optString("full_name"),o.optString("phone"),o.optText("room_name"),o.optText("move_in_date"),o.optString("move_out_date"),o.optDouble("monthly_rent").toInt(),o.optText("photo_url")) }}
